package com.ventas.security;
import com.ventas.controller.ReportController;import com.ventas.service.*;import com.ventas.security.AuthModels.Identity;import com.ventas.exception.ApiExceptionHandler;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ReportController.class) @ActiveProfiles("db") @Import({ApiSecurityConfig.class,SecurityConfig.class,ApiExceptionHandler.class})
class ReportApiTest{
 @Autowired MockMvc mvc;@MockBean AuthService auth;@MockBean ReportService service;void login(String...p){when(auth.authenticate(anyString(),anyString())).thenReturn(new Identity(1,"cuenta","N","A","ADM",false,Set.of(p),UUID.randomUUID(),OffsetDateTime.now().plusHours(1)));}
 @Test void anonymousCannotReadReports()throws Exception{mvc.perform(get("/api/reportes/ventas?desde=2026-10-01&hasta=2026-10-24")).andExpect(status().isUnauthorized());}
 @Test void inventoryPermissionDoesNotExposeSales()throws Exception{login("REP.INVENTARIO");mvc.perform(get("/api/reportes/ventas?desde=2026-10-01&hasta=2026-10-24").header("Authorization","Bearer test")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void exportHasSeparatePermission()throws Exception{login("REP.VENTAS");mvc.perform(get("/api/reportes/ventas/csv?desde=2026-10-01&hasta=2026-10-24").header("Authorization","Bearer test")).andExpect(status().isForbidden());}
 @Test void invalidDateAndMissingDateAreRejected()throws Exception{login("REP.VENTAS");mvc.perform(get("/api/reportes/ventas?desde=invalid&hasta=2026-10-24").header("Authorization","Bearer test")).andExpect(status().isBadRequest());}
 @Test void dashboardRequiresItsOwnPermission()throws Exception{login("INI.VER");mvc.perform(get("/api/reportes/dashboard?desde=2026-10-01&hasta=2026-10-24").header("Authorization","Bearer test")).andExpect(status().isForbidden());}
 @Test void reportsCannotBeWritten()throws Exception{login("REP.VENTAS");mvc.perform(post("/api/reportes/ventas").header("Authorization","Bearer test")).andExpect(status().isForbidden());verifyNoInteractions(service);}
}
